#include <vector>
#include <iostream>
using namespace std;

#define reep(i,f,t) for(int i=f ; i<int(t) ; ++i)
#define rep(i,n) reep(i, 0, n)

int main() {
    int n;
    while (cin >> n, n) {
        vector<int> nums(n, 0); // Use std::vector for dynamic sizing
        reep(i, 1, n)
            nums[(i*i)%n] |= 1;

        for (int i = 1; i < (n + 1) / 2; ++i) {
            int sum = 0;
            rep(j, n)
                sum += nums[j] & nums[(j + i) % n];
            cout << sum * 2 << endl;
        }
    }
    return 0;
}

